def f(I):
    h,w=len(I),len(I[0])
    from collections import deque
    seen=[[False]*w for _ in range(h)]; best=None
    for r in range(h):
        for c in range(w):
            if I[r][c]!=2 and not seen[r][c]:
                q=deque([(r,c)]); comp=[]
                while q:
                    y,x=q.popleft()
                    if not(0<=y<h and 0<=x<w) or seen[y][x] or I[y][x]==2: continue
                    seen[y][x]=True; comp.append((y,x))
                    q+= [(y+1,x),(y-1,x),(y,x+1),(y,x-1)]
                if best is None or len(comp)>len(best[0]): best=comp
    cols=sorted({c for _,c in best})
    return [[I[r][c] if (r,c) in {(y,x) for y,x in best} else 2 for c in cols] for r in range(h)]
