import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
from collections import Counter
def comps(g,bg):
    seen=set(); res=[]
    H,W=len(g),len(g[0])
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                q=[(r,c)]; seen.add((r,c)); cur=[]
                while q:
                    y,x=q.pop(); cur.append((y,x,g[y][x]))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]!=bg and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                res.append(sorted(cur))
    return res
# Hypothesis: noise cells join the adjacent object (recolor by majority neighbor, excluding bg).
# Then: every component translates (rigidly, same color pattern) to assemble ONE connected blob.
# Find translation per component by matching colors: output cells colored v must be union of translated input comps colored v.
for n in range(1,9):
    I=G[f'Demo pair {n} input']; O=G[f'Demo pair {n} output']
    bgi=Counter(x for row in I for x in row).most_common(1)[0][0]
    noise=min(set(x for row in I for x in row)-{bgi},key=lambda x:sum(r.count(x) for r in I))
    H,W=len(I),len(I[0])
    I2=[row[:] for row in I]
    for r in range(H):
        for c in range(W):
            if I[r][c]==noise:
                nb=[I[y][x] for y,x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0<=y<H and 0<=x<W]
                col=max(nb,key=lambda v:nb.count(v))
                if col!=bgi: I2[r][c]=col
    ci=comps(I2,bgi); co=comps(O,bgo:=Counter(x for row in O for x in row).most_common(1)[0][0])
    # each input comp keeps its color set; find all translations placing it inside output's cell set with matching colors
    outcells={(r,c,O[r][c]) for r in range(len(O)) for c in range(len(O[0])) if O[r][c]!=0}
    for i,c_ in enumerate(ci):
        offs=[]
        for (r0,c0,v) in c_:
            for (rr,cc,cv) in outcells:
                dr,dc=rr-r0,cc-c0
                if all(outcells.get((r+dr,c+dc))==v for r,c,v in c_):
                    offs.append((dr,dc))
        print('pair',n,'comp',i,'size',len(c_),'valid translations:',offs[:6],'count',len(offs))

