G=load()
from collections import Counter
def comps(g,bg):
    seen=set(); res=[]
    H,W=len(g),len(g[0])
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                q=[(r,c)]; seen.add((r,c)); cur=[]
                while q:
                    y,x=q.pop(); cur.append((y,x,g[y][x]))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]!=bg and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                res.append(sorted(cur))
    return res
def solve(I):
    bgi=Counter(x for row in I for x in row).most_common(1)[0][0]
    H,W=len(I),len(I[0])
    # absorb noise: recolor noise cell to nearest non-bg non-noise object color (Chebyshev, tie -> smaller dist sum)
    noises={x for x in set(v for row in I for v in row)-{bgi} if sum(r.count(x) for r in I)<min(sum(r.count(y) for r in I) for y in set(v for row in I for v in row)-{bgi,noises})} if False else None
    colors=[x for x in set(v for row in I for v in row)-{bgi}]
    noise=min(colors,key=lambda x:sum(r.count(x) for r in I))
    I2=[row[:] for row in I]
    objs=set(range(len(I[0])))-{noise}
    objcells={(r,c,I[r][c]) for r in range(H) for c in range(W) if I[r][c]!=bgi and I[r][c]!=noise}
    for r in range(H):
        for c in range(W):
            if I[r][c]==noise:
                best=None
                for (rr,cc,v) in objcells:
                    d=max(abs(rr-r),abs(cc-c))
                    key=(d,r+r*c,c)  # dummy tiebreak
                    if best is None or key<best[0]: best=(key,v)
                if best: I2[r][c]=best[1]
    ci=comps(I2,bgi)
    cs=[set(c_) for c_ in ci]; ids=list(range(len(cs)))
    def occ(grid): return {(r,c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c]!=bgi}
    moved=True
    while moved:
        moved=False
        for i in ids:
            cells=sorted(cs[i])
            new=[(r-1,c-1) for r,c,_ in cells]
            ok=all(0<=r<len(I2) and 0<=c<len(I2[0]) and (I2[r][c]==bgi or (r,c) in set(cells)) for r,c,_ in new)
            # no orth-adjacency with other comps, no overlap with other comps
            bad=False
            for j,kk in enumerate(ids):
                if kk==i: continue
                for (r,c,v) in cells:
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        if (r+dy,c+dx) in cs[kk]: bad=True
            for (r,c,v) in cells:
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    if (r+dy,c+dx) in occ([row[:] for row in I2]):
                        if (r+dy,c+dx)!=(r,c): pass
            if not bad and ok:
                for (r,c,v) in cells: I2[r][c]=bgi
                for (r,c,v) in new: I2[r][c]=v
                cs[i]=set(new); moved=True
    # crop: keep all rows up to max content row, columns 0..max content col
    mr=max(r for r in range(len(I2)) for c in range(len(I2[0])) if I2[r][c]!=bgi)+1
    mc=max(c for r in range(len(I2)) for c in range(len(I2[0])) if I2[r][c]!=bgi)+1
    return [row[:mc] for row in I2[:mr]]
ok=True
for n in range(1,9):
    I=G[f'Demo pair {n} input']; O=G[f'Demo pair {n} output']
    P=solve(I)
    m=(P==O)
    ok&=m
    print('pair',n,'match',m,(len(P),len(P[0])) if m else (len(O),len(O[0]),len(P),len(P[0])))
print('ALL',ok)

